"""Build the bilingual Federation Square case from reviewed content and asset records."""
from pathlib import Path
from html import escape as esc
import json
ROOT=Path(__file__).resolve().parents[1]
CASE=ROOT/'cases/federation-square'
data=json.loads((CASE/'case.json').read_text())
assets={a['id']:a for a in json.loads((CASE/'sources.json').read_text())['assets']}
def bi(zh,en):
    return f'<span lang="zh">{esc(zh)}</span><span lang="en">{esc(en)}</span>'
def elem(tag,pair,cls=''):
    return f'<{tag}'+(f' class="{cls}"' if cls else '')+'>'+bi(*pair)+f'</{tag}>'
figure_counts={}
def figure(id):
    figure_counts[id]=figure_counts.get(id,0)+1
    instance=id if figure_counts[id]==1 else id+'-'+str(figure_counts[id])
    a=assets[id];src=esc(a['image_url'],quote=True)
    return f'''<figure class="media {'drawing' if a['kind']=='drawing' else 'photo'}" id="{instance}"><button type="button" class="image-inspect" aria-label="Inspect image / 放大图像"><img src="{src}" loading="lazy" decoding="async" alt="{esc(a['title']['zh'],quote=True)}" data-alt-zh="{esc(a['title']['zh'],quote=True)}" data-alt-en="{esc(a['title']['en'],quote=True)}"></button><figcaption><span class="fig-id">{id.upper()}</span> {bi(a['title']['zh'],a['title']['en'])}<br>{bi(a['note']['zh'],a['note']['en'])}<br><a href="{esc(a['source_url'],quote=True)}" target="_blank" rel="noopener noreferrer">{bi(a.get('creator_zh',a['creator']),a['creator'])} · {esc(a['publisher'])} · {bi('原始出处','Original source')}</a> · {bi(a.get('date_zh',a['date']),a['date'])} · {bi(a['rights']['zh'],a['rights']['en'])}</figcaption></figure>'''
def block(b):
    kind=b['type']
    if kind in ['p','h1','h2','h3']:return elem(kind,b['text'],b.get('class',''))
    if kind=='figure':return figure(b['asset'])
    if kind=='gallery':return '<div class="photo-strip">'+''.join(figure(i) for i in b['assets'])+'</div>'
    if kind=='cards':return '<div class="grid">'+''.join('<article class="card">'+elem('h3',c['title'])+elem('p',c['text'])+'</article>' for c in b['cards'])+'</div>'
    if kind=='table':return '<div class="table-scroll" tabindex="0" role="region" aria-label="Research comparison / 研究对照"><table><thead><tr>'+''.join(elem('th',x) for x in b['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(elem('td',x) for x in row)+'</tr>' for row in b['rows'])+'</tbody></table></div>'
    if kind=='links':return '<ul class="source-list">'+''.join('<li><a href="'+esc(x['url'],quote=True)+'"'+(' target="_blank" rel="noopener noreferrer"' if x['url'].startswith('http') else '')+'>'+bi(*x['label'])+'</a></li>' for x in b['items'])+'</ul>'
    if kind=='facts':return '<div class="fact-grid">'+''.join('<div>'+elem('span',x['label'])+elem('strong',x['value'])+'</div>' for x in b['items'])+'</div>'
    if kind=='print':return '<button type="button" id="print-factsheet">'+bi('打印／保存PDF','Print / Save PDF')+'</button>'
    raise ValueError(kind)
# Same paper, type, grid and editorial vocabulary as 01. Scoped additions below.
reference=(ROOT/'docs/index.html').read_text()
base=reference.split('<style>',1)[1].split('</style>',1)[0]
css='''
[hidden]{display:none!important}html:not([data-language="en"]) [lang="en"],html[data-language="en"] [lang="zh"]{display:none!important}
header .inner{flex-wrap:wrap;padding-top:12px;padding-bottom:8px;gap:10px 20px}header .brand{font-size:11px;white-space:nowrap}.global-case-index{display:flex;gap:11px;flex-wrap:wrap;flex:1;font-size:11px}.global-case-index a{text-decoration:none}.global-case-index a[aria-current]{color:var(--rust);font-weight:700}.site-language-switch{display:flex;gap:3px}.site-language-switch button,button{font:inherit;cursor:pointer;color:inherit}.site-language-switch button{border:1px solid var(--line);background:transparent;padding:7px}.site-language-switch button[aria-pressed="true"]{background:var(--ink);color:var(--paper)}nav.chapter-nav{width:100%;gap:22px;border-top:1px solid var(--line);padding:2px 0;flex-wrap:nowrap;overflow-x:auto}nav.chapter-nav a{padding:10px 0;flex-shrink:0;font-size:12px}nav.chapter-nav a[aria-current="page"]{color:var(--rust)}nav.chapter-nav a[aria-current="page"]:after{content:'';position:absolute;bottom:3px;left:0;right:0;height:2px;background:var(--rust)}
main{min-height:75vh}section.chapter{padding:0 0 36px;border:0}.chapter-masthead{padding:36px 0 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:end;gap:20px}.chapter-masthead h2{margin:7px 0 0}.chapter-meta{font:4rem/.9 Georgia;color:#c4b8a9}.chapter-content{padding-top:28px}.chapter-content>h2{margin-top:45px}.chapter-content>h3{margin-top:34px}.chapter-content>p{line-height:1.9}.lead{font:clamp(1.1rem,1.6vw,1.5rem)/1.7 Georgia,"Noto Serif SC",serif}.grid{margin:28px 0}.fact-grid{margin:25px 0 35px}.fact-grid span[lang]{display:inline}.fact-grid strong{overflow-wrap:anywhere}.fact-grid strong span[lang]{font-size:inherit;letter-spacing:normal;color:inherit;margin:0}.media{margin:28px 0;background:transparent}.image-inspect{border:0;background:#e7e0d3;padding:0;width:100%;display:block;cursor:zoom-in}.media img{display:block;width:100%;height:auto;max-height:760px;object-fit:contain}.media:hover img{transform:none}.media figcaption{padding:10px 0;font-size:11px;line-height:1.65;overflow-wrap:anywhere}.fig-id{color:var(--rust);font-weight:700}.photo-strip{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:24px}.photo-strip .media{margin:0}.photo-strip img{height:310px;object-fit:contain}.drawing img{background:white}.drawing .image-inspect{background:white}.note{background:#ece4d8;padding:17px 20px;border-left:3px solid var(--rust);font-size:13px}.table-scroll{width:100%;overflow-x:auto;margin:25px 0}table{width:100%;border-collapse:collapse;min-width:600px;font-size:13px}td,th{text-align:left;vertical-align:top;padding:14px 12px;border-bottom:1px solid var(--line)}th{color:var(--rust);font-weight:600}.source-list{padding-left:20px;line-height:2}.chapter-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--line);padding-top:24px;margin-top:38px}.chapter-pagination a{text-decoration:none;max-width:43%;font:1.2rem Georgia}.chapter-pagination a:last-child{text-align:right}.chapter-pagination small{font:11px system-ui;display:block;color:var(--muted)}.chapter-counter{font-size:11px;color:var(--muted)}footer{border-top:1px solid var(--line);padding:24px 5vw;color:var(--muted);font-size:11px}.skip-link{position:absolute;top:-100px;left:15px;background:var(--paper);z-index:99;padding:10px}.skip-link:focus{top:5px}:focus-visible{outline:3px solid var(--rust);outline-offset:4px}.image-dialog{border:0;width:100vw;max-width:100vw;height:100dvh;max-height:100dvh;background:#191816f8;color:var(--paper);padding:60px 4vw 20px}.image-dialog::backdrop{background:#191816}.image-dialog .dialog-inner{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center}.image-dialog img{max-width:100%;max-height:75dvh;width:auto;height:auto;object-fit:contain}.image-dialog .dialog-caption{font-size:12px;text-align:center}.image-dialog button{position:absolute;right:4vw;top:16px;padding:8px 15px;background:transparent;border:1px solid var(--paper);color:var(--paper)}body:has(dialog[open]){overflow:hidden}#print-factsheet{padding:10px 20px;border:1px solid var(--ink);background:var(--ink);color:var(--paper)}
@media(max-width:850px){.hero-grid,.split,.overview-grid{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}.global-case-index{flex-basis:100%;order:3}nav.chapter-nav{order:4;gap:20px}.site-language-switch{margin-left:auto}header{position:relative}.photo-strip img{height:230px}.chapter-masthead{padding-top:26px}}
@media(max-width:540px){.grid,.photo-strip{grid-template-columns:1fr}.photo-strip figure:first-child{grid-column:auto}.photo-strip img{height:auto;max-height:420px}h1{font-size:2.8rem}.chapter-meta{font-size:3rem}.chapter-pagination a{font-size:1rem}.chapter-masthead h2{font-size:1.6rem}.global-case-index{gap:8px;font-size:10px}.container{padding-left:5vw;padding-right:5vw}p{overflow-wrap:anywhere}}
@media print{@page{size:A4 landscape;margin:10mm}header,footer,.chapter-masthead,.chapter-pagination,#print-factsheet,.skip-link,dialog{display:none!important}section.chapter{display:none!important}section#factsheet,section#factsheet *{visibility:visible!important}section#factsheet{display:block!important}section#factsheet[hidden]{display:block!important}.chapter-content{padding:0}.container{padding:0}body{background:white;font-size:9pt}#factsheet .chapter-content{display:grid;grid-template-columns:1fr 1.2fr;gap:2mm 8mm}#factsheet .chapter-content>h2,#factsheet .chapter-content>p,#factsheet .source-list{grid-column:1/-1}#factsheet .chapter-content>p{margin:2mm 0;max-width:none;font-size:9pt;line-height:1.45}#factsheet .media{margin:0}#factsheet .media figcaption{font-size:7pt;padding:2mm 0}#factsheet .fact-grid{grid-template-columns:1fr}#factsheet .fact-grid>div{padding:3mm 0}#factsheet .fact-grid strong{font-size:10pt}#factsheet .source-list{font-size:7pt;line-height:1.3;margin:0;display:flex;gap:7mm;list-style:none;padding:0}#factsheet .media img{max-height:82mm}.note{padding:8px}.media{break-inside:avoid}.media img{max-height:90mm}.fact-grid{margin:10px 0}.chapter-content>h2{margin-top:12px}.table-scroll{margin:8px 0}table{min-width:0;font-size:9pt}td,th{padding:5px}}
'''
nav=''.join(f'<a href="#{c["id"]}"><span aria-hidden="true">{c["icon"]}</span> {bi(*c["title"])}</a>' for c in data['chapters'])
case_names=[('01','../index.html','San Marco'),('02','la-rambla.html','La Rambla'),('03','piazza-del-campo.html','Siena'),('04','federation-square.html','Federation Square'),('05','schouwburgplein.html','Schouwburgplein'),('06','place-de-la-republique.html','République')]
index=''.join(f'<a href="{url}"'+(' aria-current="page"' if n=='04' else '')+f'>{n} {label}</a>' for n,url,label in case_names)
sections=[]
for i,c in enumerate(data['chapters']):
    prev=data['chapters'][i-1] if i else None; nxt=data['chapters'][i+1] if i+1<len(data['chapters']) else None
    def page_link(other,direction):
        if not other:return '<span></span>'
        return f'<a href="#{other["id"]}"><small>{bi(*direction)}</small>{bi(*other["title"])}</a>'
    pagination='<div class="chapter-pagination">'+page_link(prev,['← 上一章','← Previous'])+f'<span class="chapter-counter">{i+1:02d} / {len(data["chapters"]):02d}</span>'+page_link(nxt,['下一章 →','Next →'])+'</div>'
    sections.append(f'<section class="chapter" id="{c["id"]}" aria-labelledby="heading-{c["id"]}"><div class="container"><div class="chapter-masthead"><div><div class="eyebrow">04 / {c["id"].upper()}</div><h2 id="heading-{c["id"]}" tabindex="-1">{bi(*c["title"])}</h2></div><div class="chapter-meta" aria-hidden="true">{i+1:02d}</div></div><div class="chapter-content">'+''.join(block(b) for b in c['blocks'])+'</div>'+pagination+'</div></section>')
script='''
(()=>{
const sections=[...document.querySelectorAll('main>section')],nav=[...document.querySelectorAll('.chapter-nav a')];
const aliases={history:'intro','figure-ground':'scale',climate:'life',sources:'conclusion','fed-gis-figure-ground':'scale','fed-verified-section':'scale','fed-original-drawing-set':'scale','fg-data-protocol-04':'scale','fg-published-federation':'scale','syntax-research-v3':'syntax','fed-evidence-audit':'conclusion'};
function render(focus=false){let raw=decodeURIComponent(location.hash.slice(1)),target=document.getElementById(raw);let id=aliases[raw]||target?.closest('section.chapter')?.id||raw;if(!sections.some(s=>s.id===id))id='intro';sections.forEach(s=>s.hidden=s.id!==id);nav.forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(focus)document.getElementById('heading-'+id).focus({preventScroll:true});window.scrollTo(0,0);if(target&&!sections.includes(target))target.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',()=>render(true));render();
function language(lang){lang=lang==='en'?'en':'zh';document.documentElement.dataset.language=lang;document.documentElement.lang=lang;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.querySelectorAll('img[data-alt-zh]').forEach(im=>im.alt=im.dataset[lang==='en'?'altEn':'altZh']);try{localStorage.setItem('great-places-language',lang)}catch{};document.title='THE GREAT PLACES · Federation Square';}
let saved;try{saved=localStorage.getItem('great-places-language')}catch{}language(saved);document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>language(b.dataset.lang)));
const dialog=document.querySelector('dialog'),large=dialog.querySelector('img'),caption=dialog.querySelector('.dialog-caption');let opener;
document.querySelectorAll('.image-inspect').forEach(b=>b.addEventListener('click',()=>{opener=b;const im=b.querySelector('img');large.src=im.currentSrc||im.src;large.alt=im.alt;caption.replaceChildren(b.closest('figure').querySelector('figcaption').cloneNode(true));dialog.showModal()}));
dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>opener?.focus());
document.getElementById('print-factsheet').onclick=()=>window.print();
})();
'''
html='''<!doctype html><html lang="zh" data-language="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Federation Square: bilingual architectural research, official GIS figure-ground, original drawings and documented public life."><title>THE GREAT PLACES · Federation Square</title><style>'''+base+css+'''</style></head><body><a class="skip-link" href="#main">'''+bi('跳至正文','Skip to content')+'''</a><header><div class="container inner"><strong class="brand eyebrow">THE GREAT PLACES · 004</strong><div class="site-language-switch" role="group" aria-label="Language / 语言"><button type="button" data-lang="zh" aria-pressed="true">中文</button><button type="button" data-lang="en" aria-pressed="false">EN</button></div><div class="global-case-index" role="navigation" aria-label="Project index / 案例索引">'''+index+'</div><nav class="chapter-nav" aria-label="Chapters / 章节">'+nav+'</nav></div></header><main id="main">'+''.join(sections)+'''</main><footer>'''+bi('资料核查：2026-11-13 · 历史图纸、2020 GIS与使用照片分别注明年代。','Sources checked 2026-11-13 · Historic drawings, 2020 GIS and use photographs are dated separately.')+'''</footer><dialog class="image-dialog" aria-label="Image inspection / 图像检查"><button type="button">'''+bi('关闭 ×','Close ×')+'''</button><div class="dialog-inner"><img alt=""><div class="dialog-caption"></div></div></dialog><script>'''+script+'</script></body></html>\n'
(ROOT/'docs/cases/federation-square.html').write_text(html.replace('><','>\n<'))
print('Built',len(html),'characters;',len(assets),'registered assets')
